finish
note "المفاتيح محفوظة في $ENV_FILE (مش بيترفع على git)."
note "علشان المفاتيح الحقيقية: شغّلي الـ wizard تاني وحطي مفاتيح Live مكانهم."
}

run_wizard "$@"; exit
